-- -----------------------------------------------------------------------------
-- TABLA: passkey_credentials (0 registros)
-- -----------------------------------------------------------------------------
CREATE TABLE passkey_credentials (
      id TEXT PRIMARY KEY,
      worker_id TEXT NOT NULL REFERENCES workers(id) ON DELETE CASCADE,
      credential_id TEXT UNIQUE NOT NULL,
      public_key TEXT NOT NULL,
      sign_count INTEGER NOT NULL DEFAULT 0,
      device_name TEXT NOT NULL DEFAULT 'Dispositivo Móvil',
      status TEXT NOT NULL DEFAULT 'active', -- 'active', 'revoked'
      aaguid TEXT,
      enrolled_at TEXT DEFAULT CURRENT_TIMESTAMP,
      last_used_at TEXT
    );

-- -----------------------------------------------------------------------------
-- TABLA: nfc_cards (0 registros)
-- -----------------------------------------------------------------------------
CREATE TABLE nfc_cards (
      id TEXT PRIMARY KEY,
      worker_id TEXT NOT NULL REFERENCES workers(id) ON DELETE CASCADE,
      card_uid TEXT UNIQUE NOT NULL,
      status TEXT NOT NULL DEFAULT 'active', -- 'active', 'revoked', 'lost'
      issued_by TEXT REFERENCES workers(id),
      issued_at TEXT DEFAULT CURRENT_TIMESTAMP,
      revoked_at TEXT
    );

