-- -----------------------------------------------------------------------------
-- TABLA: tenant_settings (1 registros)
-- -----------------------------------------------------------------------------
CREATE TABLE tenant_settings (
      id TEXT PRIMARY KEY DEFAULT 'current_tenant',
      entity_name TEXT NOT NULL DEFAULT 'Ministerio del Poder Popular para la Comunicación y la Información',
      entity_short_name TEXT NOT NULL DEFAULT 'MIPPCI',
      slogan TEXT NOT NULL DEFAULT 'Bienestar y Soberanía Alimentaria Institucional',
      logo_url TEXT,
      primary_color TEXT DEFAULT '#0284c7',
      secondary_color TEXT DEFAULT '#0ea5e9',
      updated_at TEXT DEFAULT CURRENT_TIMESTAMP
    , is_initialized INTEGER DEFAULT 1, is_demo_mode INTEGER DEFAULT 1, supervisor_qr_mode INTEGER DEFAULT 0);

INSERT INTO "tenant_settings" ("id", "entity_name", "entity_short_name", "slogan", "logo_url", "primary_color", "secondary_color", "updated_at", "is_initialized", "is_demo_mode", "supervisor_qr_mode") VALUES ('current_tenant', 'Ministerio del Poder Popular para la Comunicación y la Información', 'MIPPCI', 'Bienestar y Soberanía Alimentaria Institucional', 'data:image/png;base64,', '#0284c7', '#0ea5e9', '2026-10-20 15:42:02', 1, 0, 0);

-- -----------------------------------------------------------------------------
-- TABLA: system_notifications (1 registros)
-- -----------------------------------------------------------------------------
CREATE TABLE system_notifications (
      id TEXT PRIMARY KEY,
      campaign_id TEXT REFERENCES delivery_campaigns(id) ON DELETE CASCADE,
      title TEXT NOT NULL,
      message TEXT NOT NULL,
      target_group TEXT NOT NULL DEFAULT 'all',
      notification_type TEXT NOT NULL DEFAULT 'jornada', -- 'jornada', 'alerta', 'recordatorio'
      created_at TEXT DEFAULT CURRENT_TIMESTAMP
    );

INSERT INTO "system_notifications" ("id", "campaign_id", "title", "message", "target_group", "notification_type", "created_at") VALUES ('cd2e48cc-5962-4e6e-acf1-c959c47c9d57', 'b64692f5-8a7b-425e-9211-4a84a4776b3a', '📢 ¡Jornada Integral de Despacho Activa!', 'Se encuentra activo el despacho de beneficios organizados por mesas de entrega (Víveres, Higiene, Útiles y Proteínas en Cadena de Frío). Presente su credencial o QR biométrico.', 'all', 'jornada', '2026-10-20 15:42:02');

-- -----------------------------------------------------------------------------
-- TABLA: payroll_sync_logs (0 registros)
-- -----------------------------------------------------------------------------
CREATE TABLE payroll_sync_logs (
      id TEXT PRIMARY KEY,
      batch_id TEXT NOT NULL,
      source TEXT NOT NULL,
      records_processed INTEGER NOT NULL DEFAULT 0,
      records_failed INTEGER NOT NULL DEFAULT 0,
      status TEXT NOT NULL DEFAULT 'success',
      details TEXT,
      executed_at TEXT DEFAULT CURRENT_TIMESTAMP
    );

-- =============================================================================
-- ÍNDICES Y RESTRICCIONES ANTI-FRAUDE
-- =============================================================================
CREATE UNIQUE INDEX idx_unique_daily_claim 
    ON deliveries (worker_id, entitlement_id);

-- =============================================================================
-- TRIGGERS AUTOMÁTICOS
-- =============================================================================
CREATE TRIGGER trg_mark_entitlement_claimed
    AFTER INSERT ON deliveries
    BEGIN
      UPDATE daily_entitlements
      SET status = 'claimed'
      WHERE id = NEW.entitlement_id;
    END;

COMMIT;
PRAGMA foreign_keys = ON;
